rection:column}.source-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.source-grid>article{border:1px solid rgba(255,255,255,.08);border-radius:13px;padding:22px}.source-grid span{color:#61dda8;font-size:10px;letter-spacing:.1em}.source-grid p{font:16px/1.65 Georgia,serif;color:#c5d5ce}.source-grid article>div{padding:12px;background:#091512;margin-top:8px;color:#81978e;line-height:1.55}.source-grid b{display:block;color:#68dfad;margin-bottom:4px}.task-head{text-align:center;margin-bottom:24px}.task-head h2,.diagnosis-result h2,.prescription h2{font-size:28px;margin:9px 0}.label-list{display:grid;gap:9px}.label-list article{display:grid;grid-template-columns:1fr auto;gap:14px;align-items:center;padding:14px;border:1px solid rgba(255,255,255,.08);border-radius:11px}.label-list p{margin:0;color:#c5d5ce;font-family:Georgia,serif}.label-list article>div{display:flex;gap:5px}.label-list button,.function-tests button{border:1px solid #294138;background:#091512;color:#71887e;border-radius:7px;padding:7px 10px;cursor:pointer}.label-list button.selected,.function-tests button.selected{border-color:#5be0a8;color:#e2f8ed;background:rgba(70,219,154,.08)}.function-tests{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.function-tests article{padding:16px;border:1px solid rgba(255,255,255,.08);border-radius:11px;display:flex;flex-direction:column;gap:8px}.function-tests b{font-size:13px}.function-tests button{text-align:left;line-height:1.45}.diagnosis-result,.prescription{text-align:center;max-width:1000px;margin:auto}.score-pair{display:flex;justify-content:center;gap:12px;margin:22px}.score-pair p{min-width:140px;padding:17px;background:#091512;border-radius:12px;display:flex;flex-direction:column;margin:0}.score-pair small{color:#647b71}.score-pair strong{font-size:30px}.diagnosis-result>p{color:#899e95;line-height:1.65}.priority{margin-top:25px;padding:20px;border:1px solid rgba(87,224,168,.28);background:rgba(67,218,153,.07);border-radius:12px;display:flex;flex-direction:column;gap:8px}.priority span{color:#5ddda7;font-size:10px}.priority small{color:#738a80}.route{display:grid;grid-template-columns:1fr auto 1fr auto 1fr auto 1fr;align-items:center;gap:8px;margin:28px 0}.route article{min-height:130px;padding:17px;border:1px solid rgba(255,255,255,.08);border-radius:12px;display:flex;flex-direction:column;text-align:left}.route article.active{border-color:#5de0a8;background:rgba(65,218,151,.08)}.route small{color:#5f766d}.route b{margin:12px 0 6px}.route p{margin:0;color:#6f867c;font-size:11px;line-height:1.5}.route i{color:#58dda6}footer{margin-top:auto;padding-top:22px;border-top:1px solid rgba(255,255,255,.08);display:flex;align-items:center;justify-content:space-between}footer span{color:#5f766d;font-size:11px}footer button:disabled{opacity:.35;cursor:not-allowed}@media(max-width:900px){.demo-app{grid-template-columns:76px minmax(0,1fr)}.source-grid,.function-tests{grid-template-columns:1fr}.route{grid-template-columns:1fr}.route i{transform:rotate(90deg)}}@media(max-width:560px){.demo-app{display:block}.coach-main{padding:0 15px 40px}header{align-items:flex-start;flex-direction:column;padding:18px 0}.case-banner{align-items:flex-start;flex-direction:column}.steps{overflow:auto;grid-template-columns:repeat(4,120px)}.label-list article{grid-template-columns:1fr}.work-panel{padding:18px}}
</style>
